import { injectable } from "inversify";

import { FrontendApplicationContribution } from "@theia/core/lib/browser";

@injectable()
export class CustomFontFamiliesContribution implements FrontendApplicationContribution {

    constructor() { }

    async onStart(): Promise<void> {
        const fontFamiliesList = ["https://fonts.googleapis.com/css2?family=Fira+Code:wght@300;400;500;600;700&display=swap", "https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;0,800;1,100;1,200;1,300;1,400;1,500;1,600;1,700;1,800&display=swap", "https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600;700;800;900&display=swap"]
        if (document.head) {
            let preconnectLinkTag = document.createElement('link');
            preconnectLinkTag.rel = 'preconnect';
            preconnectLinkTag.href = 'https://fonts.gstatic.com';
            document.head.appendChild(preconnectLinkTag);

            fontFamiliesList.forEach((eachFontFamily) => {
                let fontFamilyLinkTag = document.createElement('link');
                fontFamilyLinkTag.rel = 'stylesheet';
                fontFamilyLinkTag.href = eachFontFamily;
                document.head.appendChild(fontFamilyLinkTag);
            })
        }
    }
}
