import { injectable, inject } from "inversify";

import URI from "@theia/core/lib/common/uri";
import { Command, CommandContribution, CommandRegistry } from '@theia/core/lib/common/command';
import { MiniBrowserOpenHandler } from '@theia/mini-browser/lib/browser/mini-browser-open-handler'

export namespace MiniBrowserCommands {
    export const OPEN_MAIN_URL: Command = {
        id: 'mini-browser.main.openUrl',
        category: 'Preview',
        label: 'Open URL'
    }
}

@injectable()
export class CCBPCustomCommandsContribution implements CommandContribution {

    constructor(@inject(MiniBrowserOpenHandler) protected readonly miniBrowserOpenHandler: MiniBrowserOpenHandler) { }

    registerCommands(commands: CommandRegistry): void {
        commands.registerCommand(MiniBrowserCommands.OPEN_MAIN_URL, {
            execute: (arg: string, options: any) => this.miniBrowserOpenHandler.open(new URI(arg), { mode: 'activate', toolbar: 'hide', ...options })
        });
    }
}
