import { injectable, inject } from "inversify"

import { FileService } from '@theia/filesystem/lib/browser/file-service'
import { FrontendApplicationContribution } from "@theia/core/lib/browser"
import { WorkspaceService } from '@theia/workspace/lib/browser/workspace-service'
import { MonacoSnippetSuggestProvider } from '@theia/monaco/lib/browser/monaco-snippet-suggest-provider'

import { CustomCodeSnippetsContribution, fileExtenion, globalTheiaPath } from "../common"

@injectable()
export class CustomCodeSnippetsExtensionContribution implements FrontendApplicationContribution {

    constructor(
        @inject(FileService) protected readonly fileSystemWatcher: FileService,
        @inject(WorkspaceService) protected readonly workspaceService: WorkspaceService,
        @inject(CustomCodeSnippetsContribution) protected readonly customCodeSnippetsServer: CustomCodeSnippetsContribution,
        @inject(MonacoSnippetSuggestProvider) protected readonly monacoSnippetSuggestProvider: MonacoSnippetSuggestProvider
    ) { }

    async onStart(): Promise<void> {
        const currentWorkspacePath = this.workspaceService.workspace?.resource.path.toString()
        let workspaceTheiaPath: any
        let projectCodeSnippetsFolders = []
        if (currentWorkspacePath) {
            workspaceTheiaPath = `${currentWorkspacePath}/.theia`
            projectCodeSnippetsFolders = await this.customCodeSnippetsServer.getFilesInWorkspaceTheiaFolder(workspaceTheiaPath)
        }
        const codeSnippetsFolders = await this.customCodeSnippetsServer.getFilesInGlobalTheiaFolder()

        codeSnippetsFolders.forEach((element: any) => {
            const fileName = element.split('.')
            this.monacoSnippetSuggestProvider.fromURI(`${globalTheiaPath}/${element}`, { language: fileName[0], source: `${fileName} Language Basics` })
        });

        projectCodeSnippetsFolders.forEach((element: any) => {
            const fileName = element.split('.')
            this.monacoSnippetSuggestProvider.fromURI(`${workspaceTheiaPath}/${element}`, { language: fileName[0], source: `${fileName} Language Basics` })
        });

        this.fileSystemWatcher.onDidFilesChange(async (event) => {
            const fileName = event.changes[0]?.resource.path.base.split(".")
            if (fileName[1] === fileExtenion) {
                this.monacoSnippetSuggestProvider.fromURI(`${event.changes[0]?.resource.path}`, { language: fileName[0], source: `${fileName} Language Basics` })
            }
        })
    }
}
