import { ContainerModule } from 'inversify';

import { FrontendApplicationContribution, WebSocketConnectionProvider } from '@theia/core/lib/browser';

import { CustomCodeSnippetsContribution, CCBPProjectServicePath } from '../common';

import { CustomCodeSnippetsExtensionContribution } from './custom-code-snippets-extension-contribution';

export default new ContainerModule(bind => {
    bind(FrontendApplicationContribution).to(CustomCodeSnippetsExtensionContribution);
    bind(CustomCodeSnippetsContribution).toDynamicValue(context => WebSocketConnectionProvider.createProxy(context.container, CCBPProjectServicePath)).inSingletonScope();
});
